document.addEventListener('click',e=>{
  const pageButton=e.target.closest('[data-page]');
  if(pageButton){state.currentPage=pageButton.dataset.page;if(state.currentPage==='managers'&&!currentUserIsManager())api('/api/managers').then(data=>{managerData=data;render()}).catch(error=>toast(error.message,'error'));save();render();return}
  const tab=e.target.closest('[data-market-tab]');
  if(tab){marketTab=tab.dataset.marketTab;render();return}
  const button=e.target.closest('[data-action]');
  if(!button)return;
  const {action,id}=button.dataset;
  if(action==='close-modal'){closeModal();return}
  if(action==='invite-manager'){if(currentUserIsManager()){toast('Somente o administrador pode convidar managers.','error');return}openInviteManager();return}
  if(action==='cancel-invite'){const invite=managerData.invites.find(item=>item.id===id);api(`/api/invites/${encodeURIComponent(id)}`,{method:'DELETE'}).then(async result=>{serverRevision=result.revision;if(invite){const club=state.clubs.find(item=>item.id===invite.clubId);if(club)club.manager=''}managerData=await api('/api/managers');render();toast('Convite cancelado.')}).catch(error=>toast(error.message,'error'));return}
  if(action==='copy-invite'){const input=document.querySelector('.invite-link');input?.select();navigator.clipboard?.writeText(input?.value||'').then(()=>toast('Link copiado.')).catch(()=>toast('Selecione e copie o link exibido.','error'));return}
  if(currentUserIsManager()&&['create-team','create-competition','schedule-match','team-menu'].includes(action)){toast('Essa ação é exclusiva do administrador da liga.','error');return}
  if(action==='competition-switch'){
    if(!state.competitions.length){modal('create-competition');return}
    const next=state.competitions[(state.competitions.indexOf(state.currentLeague)+1)%state.competitions.length];
    state.currentLeague=next;state.selectedSquad='';save();render();toast(`Competição selecionada: ${next}.`);return;
  }
  const modalActions=['create-team','add-player','announce-player','create-competition','cash-transfer','schedule-match','register-match','create-auction','bid','loan','buy','end-loan','player-menu','team-menu'];
  if(modalActions.includes(action)){
    if(action==='register-match')return modal('match-result');
    if(action==='loan'&&state.players.find(player=>player.id===id)?.clubId===currentClubId()){toast('Este atleta já está no seu clube.','error');return}
    if(action==='team-menu'){modal('team-menu',id);return}
    if(action==='player-menu'&&!state.players.find(player=>player.id===id)?.listed){toast('Este atleta ainda não está anunciado.');return}
    modal(action,id);return;
  }
  if(action==='match-result'){modal('match-result',id);return}
  if(action==='view-squad'){
    state.selectedSquad=id;state.currentClubByCompetition[state.currentLeague]=id;state.currentPage='squad';save();render();return;
  }
  if(action==='team-squad'){
    state.selectedSquad=id;state.currentClubByCompetition[state.currentLeague]=id;state.currentPage='squad';closeModal();save();render();return;
  }
  if(action==='team-add-player'){
    if(currentUserIsManager()&&id!==currentClubId()){toast('Você só pode editar o elenco do seu clube.','error');return}
    state.selectedSquad=id;closeModal();modal('add-player');return;
  }
});
document.addEventListener('change',e=>{if(e.target.id==='squad-selector'){state.selectedSquad=currentUserIsManager()?currentClubId():e.target.value;state.currentClubByCompetition[state.currentLeague]=state.selectedSquad;save();render()}if(e.target.id==='market-position')filterMarket()});document.addEventListener('input',e=>{if(e.target.id==='market-search'){marketSearch=e.target.value;filterMarket()}});function filterMarket(){const body=document.querySelector('#market-body');if(!body)return;const pos=document.querySelector('#market-position')?.value||'',q=(document.querySelector('#market-search')?.value||'').toLowerCase();const rows=[...body.querySelectorAll('tr')];rows.forEach(row=>{const text=row.textContent.toLowerCase();const matchQuery=!q||text.includes(q);const matchPos=!pos||text.includes(pos);row.style.display=matchQuery&&matchPos?'':'none'})}document.querySelector('#help-button').addEventListener('click',()=>toast('Use a navegação para acompanhar competições, elencos, jogos e negociações.'));document.querySelector('#notification-button').addEventListener('click',()=>toast('Você está em dia. Nenhuma nova notificação.'));document.querySelector('#profile-button').addEventListener('click',async()=>{if(!authUser)return;try{await api('/api/logout',{method:'POST'});}catch{}authUser=null;authMode='login';renderAuth()});document.querySelector('#top-profile-button').addEventListener('click',()=>document.querySelector('#profile-button').click());document.addEventListener('click',e=>{const mode=e.target.closest('[data-auth-mode]')?.dataset.authMode;if(mode){authMode=mode;renderAuth();return}});document.addEventListener('submit',async e=>{if(e.target.id!=='auth-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target).entries()),mode=e.target.dataset.mode,error=document.querySelector('#auth-error');try{const payload=mode==='setup'?await api('/api/setup',{method:'POST',body:JSON.stringify({...data,initialState:legacyState()})}):mode==='register'?await api('/api/register',{method:'POST',body:JSON.stringify(data)}):await api('/api/login',{method:'POST',body:JSON.stringify(data)});applySession(payload);history.replaceState({},'',location.pathname)}catch(err){error.textContent=err.message}});startApp();
